(()=>{'use strict';const config=window.FENEK_CONFIG||{},id=Number(config.metrikaId);let ready=false,consent=false,pending=[];const allowed=new Set(['lead_open','lead_start','lead_submit','lead_success','payment_lead_success','cargo_lead_success','lead_error','telegram_click','max_click','cargo_calculate','exchange_select']);const trackingKeys=['utm_source','utm_medium','utm_campaign','utm_content','utm_term','yclid'];function storageGet(key){try{return sessionStorage.getItem(key)}catch{return null}}function storageSet(key,value){try{sessionStorage.setItem(key,value)}catch{}}let attribution={};try{attribution=JSON.parse(storageGet('fenek_attribution')||'{}')}catch{}const params=new URLSearchParams(location.search);if(trackingKeys.some(k=>params.has(k))){attribution={landing:location.pathname};trackingKeys.forEach(k=>{if(params.has(k))attribution[k]=params.get(k).slice(0,250)});storageSet('fenek_attribution',JSON.stringify(attribution))}window.FenekAnalytics={attribution,goal(name,params={}){if(!allowed.has(name))return;const clean={};['form','page','service','reason','transport'].forEach(k=>{if(params[k]!==undefined)clean[k]=String(params[k]).slice(0,80)});document.dispatchEvent(new CustomEvent('fenek:goal',{detail:{name,params:clean}}));if(!id)return;if(ready&&consent)window.ym(id,'reachGoal',name,clean);else if(consent&&pending.length<30)pending.push([name,clean])}};function start(){if(ready||!Number.isSafeInteger(id)||id<=0)return;consent=true;window.ym=window.ym||function(){(window.ym.a=window.ym.a||[]).push(arguments)};window.ym.l=Date.now();const script=document.createElement('script');script.async=true;script.src='https://mc.yandex.ru/metrika/tag.js';document.head.append(script);window.ym(id,'init',{clickmap:true,trackLinks:true,accurateTrackBounce:true,webvisor:false,trackHash:false});ready=true;pending.forEach(([name,p])=>window.ym(id,'reachGoal',name,p));pending=[]}let saved;try{saved=localStorage.getItem('fenek_analytics_consent')}catch{}if(id>0){if(config.analyticsConsentRequired===false||saved==='yes')start();else if(saved!=='no'){const banner=document.createElement('aside');banner.className='analytics-consent';banner.setAttribute('aria-label','Настройки аналитики');banner.innerHTML='<p>Используем Яндекс Метрику, чтобы улучшать сайт. <a href="privacy.html">Подробнее</a></p><div><button type="button" data-choice="yes">Разрешить</button><button type="button" data-choice="no">Только необходимые</button></div>';document.body.append(banner);banner.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{try{localStorage.setItem('fenek_analytics_consent',b.dataset.choice)}catch{}if(b.dataset.choice==='yes')start();else pending=[];banner.remove()}))}}document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(!a)return;try{const url=new URL(a.href);if(url.hostname==='t.me')window.FenekAnalytics.goal('telegram_click',{page:location.pathname});if(url.hostname==='max.ru')window.FenekAnalytics.goal('max_click',{page:location.pathname})}catch{}})})();
